let new_exp = player.exp + exp_gained;
    let threshold = player.level * 100;
    if new_exp >= threshold {
        Player {
            id: player.id,
            pos: player.pos,
            stats: Stats {
                hp: player.stats.max_hp + 10,
                max_hp: player.stats.max_hp + 10,
                attack: player.stats.attack + 2,
                defense: player.stats.defense + 1,
            },
            exp: new_exp - threshold,
            level: player.level + 1,
        }
    } else {
        Player {
            id: player.id,
            pos: player.pos,
            stats: player.stats,
            exp: new_exp,
            level: player.level,
        }
    }

let remaining = current_hp - damage;
    if remaining > 0 {
        remaining
    } else {
        0
    }

let raw = attacker_atk - defender_def;
    if raw > 1 {
        raw
    } else {
        1
    }

let new_x = pos.x + dx;
    let new_y = pos.y + dy;
    if new_x >= 0 && new_x < map_width && new_y >= 0 && new_y < map_height {
        Point { x: new_x, y: new_y }
    } else {
        Point {
            x: if pos.x >= 0 && pos.x < map_width { pos.x } else { 0 },
            y: if pos.y >= 0 && pos.y < map_height { pos.y } else { 0 },
        }
    }

// 读取转出账户
    let from_acc = match Database.find_account(from_id) {
        Some(acc) => acc,
        None => return Err(TransferError.AccountNotFound(from_id)),
    };

    // 读取转入账户
    let to_acc = match Database.find_account(to_id) {
        Some(acc) => acc,
        None => return Err(TransferError.AccountNotFound(to_id)),
    };

    // 余额检查
    if from_acc.balance < amount {
        return Err(TransferError.InsufficientBalance(
            required: amount, 
            available: from_acc.balance
        ));
    }

    // 不可变更新 (纯数据变换)
    let new_from = { ...from_acc, balance: from_acc.balance - amount };
    let new_to = { ...to_acc, balance: to_acc.balance + amount };

    // 提交副作用
    Database.update_account(new_from);
    Database.update_account(new_to);

    let ts = Clock.now_timestamp();
    AuditLog.info("Transfer completed successfully");

    Ok(TransferReceipt {
        tx_id: "TX_" + ts.to_string(),
        from_id: from_id,
        to_id: to_id,
        amount: amount,
        timestamp: ts,
    })

